# --- scene_4 (code_final.py) ---
class EquipmentAndPlugLoads(Scene):
    def construct(self):
        self.camera.background_color = P_DEEP_DARK

        GREY_LINE = "#2C3545"

        def device_glow(center, color=P_ORANGE):
            """Soft layered glow under a heat source (Heating internal_heat_gain style)."""
            return VGroup(
                Circle(radius=1.05, color=color, stroke_width=0, fill_opacity=0.05).move_to(center),
                Circle(radius=0.65, color=color, stroke_width=0, fill_opacity=0.10).move_to(center),
                Circle(radius=0.32, color=color, stroke_width=0, fill_opacity=0.18).move_to(center),
            )

        def rising_heat_waves(origin, n=3, color=P_ORANGE, height=1.35, x_spread=0.32, stroke_width=2.0):
            """Sine-wavy radiation rising upward from a device (Heating ParametricFunction style)."""
            ox, oy = float(origin[0]), float(origin[1])
            waves = VGroup()
            for i in range(n):
                x0 = ox + (i - (n - 1) / 2) * x_spread
                phase = i * 0.85

                def _path(t, x0=x0, oy=oy, phase=phase, height=height):
                    return np.array([
                        x0 + np.sin(t * 5.0 + phase) * 0.08,
                        oy + t * height,
                        0.0,
                    ])

                wave = ParametricFunction(
                    _path,
                    t_range=[0, 1.0],
                    color=color,
                    stroke_width=stroke_width,
                ).set_opacity(0.8)
                waves.add(wave)
            return waves

        def create_smooth_wave(x_shift, y0=-0.2, y1=1.2, color=P_ORANGE):
            """Smooth VMobject heat ribbon (Heating create_wave style)."""
            pts = [
                [x_shift + 0.09 * np.sin(y * 5), y, 0]
                for y in np.linspace(y0, y1, 28)
            ]
            wave = VMobject(color=color, stroke_width=2.2, stroke_opacity=0.75)
            wave.set_points_smoothly(pts)
            return wave

        title = scene_title("Geräte und Steckerlasten")
        play_typed_title(self, title)

        floor = Line(LEFT * 6.5 + DOWN * 2.5, RIGHT * 6.5 + DOWN * 2.5, color=GREY_LINE, stroke_width=2)

        desk_surface = Line(LEFT * 4.8 + DOWN * 0.8, LEFT * 0.2 + DOWN * 0.8, color=P_CYAN, stroke_width=3)
        leg_left = Line(LEFT * 4.5 + DOWN * 0.8, LEFT * 4.5 + DOWN * 2.5, color=P_CYAN, stroke_width=2)
        leg_right = Line(LEFT * 0.5 + DOWN * 0.8, LEFT * 0.5 + DOWN * 2.5, color=P_CYAN, stroke_width=2)
        desk = VGroup(desk_surface, leg_left, leg_right)

        grid = VGroup()
        for x in range(-6, 7, 2):
            grid.add(Line(x * RIGHT + UP * 3.5, x * RIGHT + DOWN * 2.5, color=GREY_LINE, stroke_width=0.8, stroke_opacity=0.3))
        for y in range(-2, 4, 2):
            grid.add(Line(LEFT * 6.5 + y * UP, RIGHT * 6.5 + y * UP, color=GREY_LINE, stroke_width=0.8, stroke_opacity=0.3))

        self.play(
            Create(grid, run_time=1.0),
            Create(floor, run_time=1.0),
            Create(desk, run_time=1.0),
        )

        # Beat 1: Laptop lands on desk
        laptop_base = Rectangle(width=1.4, height=0.12, color=P_CYAN, fill_color="#1F2833", fill_opacity=0.9, stroke_width=2)
        laptop_screen = Rectangle(width=1.3, height=0.85, color=P_CYAN, fill_color="#0B0C10", fill_opacity=0.9, stroke_width=2)
        laptop_screen.next_to(laptop_base, UP, buff=0)
        laptop = VGroup(laptop_base, laptop_screen)

        start_laptop_pos = LEFT * 2.5 + UP * 2.5
        target_laptop_pos = LEFT * 2.5 + DOWN * 0.32
        laptop.move_to(start_laptop_pos)


        self.play(
            laptop.animate.move_to(target_laptop_pos),
            rate_func=rate_functions.ease_out_bounce,
            run_time=1.4,
        )


        # Beat 2: Rising wavy radiation from laptop (Heating-style)
        laptop_heat_origin = target_laptop_pos + UP * 0.15
        laptop_glow = device_glow(laptop_heat_origin, color=P_ORANGE)
        laptop_waves = rising_heat_waves(
            laptop_heat_origin + DOWN * 0.05,
            n=4,
            color=P_ORANGE,
            height=1.45,
            x_spread=0.28,
        )
        laptop_ribbons = VGroup(
            create_smooth_wave(-2.75, y0=-0.35, y1=1.15, color=P_ORANGE),
            create_smooth_wave(-2.50, y0=-0.35, y1=1.25, color=P_RED),
            create_smooth_wave(-2.25, y0=-0.35, y1=1.15, color=P_ORANGE),
        )

        heat_label_laptop = Text("Wärmeabgabe", font_size=22, color=P_ORANGE)
        heat_label_laptop.move_to(LEFT * 2.5 + UP * 1.65)

        self.play(
            FadeIn(laptop_glow),
            laptop.animate.set_color(P_ORANGE),
            run_time=0.9,
        )
        self.play(
            LaggedStart(
                *[Create(w) for w in laptop_waves],
                *[Create(r) for r in laptop_ribbons],
                lag_ratio=0.08,
            ),
            run_time=1.8,
        )
        self.play(
            laptop_waves.animate.shift(UP * 0.35).set_opacity(0.45),
            laptop_ribbons.animate.shift(UP * 0.3).set_opacity(0.4),
            laptop_glow[2].animate.scale(1.25),
            laptop_glow[1].animate.scale(1.15),
            FadeIn(heat_label_laptop, shift=UP * 0.1),
            run_time=1.6,
        )
        self.play(
            laptop_waves.animate.shift(UP * 0.25).set_opacity(0.25),
            laptop_ribbons.animate.shift(UP * 0.2).set_opacity(0.25),
            rate_func=there_and_back,
            run_time=1.4,
        )

        # Beat 3: Server rack drops in
        rack_frame = Rectangle(width=1.8, height=3.2, color=P_CYAN, fill_color="#1F2833", fill_opacity=0.9, stroke_width=2)
        slots = VGroup()
        for i in range(5):
            slot_y = 1.0 - i * 0.5
            slot_rect = Rectangle(width=1.4, height=0.35, color=GREY_LINE, fill_color="#0B0C10", fill_opacity=0.8, stroke_width=1.5)
            slot_rect.move_to(UP * slot_y)
            d1 = Dot(slot_rect.get_left() + RIGHT * 0.2, radius=0.04, color=P_CYAN)
            d2 = Dot(slot_rect.get_left() + RIGHT * 0.35, radius=0.04, color=P_ORANGE)
            slots.add(VGroup(slot_rect, d1, d2))

        server_rack = VGroup(rack_frame, slots)
        start_rack_pos = RIGHT * 3.0 + UP * 3.5
        target_rack_pos = RIGHT * 3.0 + DOWN * 0.9
        server_rack.move_to(start_rack_pos)



        self.play(
            server_rack.animate.move_to(target_rack_pos),
            rate_func=rate_functions.ease_out_bounce,
            run_time=1.4,
        )
     
        # Beat 4: Rising radiation plumes from server (not side arrows)
        server_origin = target_rack_pos + UP * 0.4
        server_glow = device_glow(server_origin, color=P_ORANGE)
        server_waves_left = rising_heat_waves(
            server_origin + LEFT * 0.55 + DOWN * 0.2,
            n=3, color=P_ORANGE, height=1.55, x_spread=0.22, stroke_width=2.0,
        )
        server_waves_right = rising_heat_waves(
            server_origin + RIGHT * 0.55 + DOWN * 0.2,
            n=3, color=P_RED, height=1.55, x_spread=0.22, stroke_width=2.0,
        )
        server_top_waves = rising_heat_waves(
            server_origin + UP * 0.9,
            n=3, color=P_ORANGE, height=1.1, x_spread=0.35, stroke_width=2.2,
        )
        server_ribbons = VGroup(
            create_smooth_wave(2.55, y0=-1.4, y1=0.6, color=P_ORANGE),
            create_smooth_wave(3.00, y0=-1.2, y1=0.9, color=P_RED),
            create_smooth_wave(3.45, y0=-1.4, y1=0.6, color=P_ORANGE),
        )

        self.play(
            FadeIn(server_glow),
            rack_frame.animate.set_color(P_ORANGE),
            run_time=0.9,
        )
        self.play(
            LaggedStart(
                *[Create(w) for w in server_waves_left],
                *[Create(w) for w in server_waves_right],
                *[Create(w) for w in server_top_waves],
                *[Create(r) for r in server_ribbons],
                lag_ratio=0.05,
            ),
            run_time=2.0,
        )
        self.play(
            server_waves_left.animate.shift(UP * 0.4).set_opacity(0.4),
            server_waves_right.animate.shift(UP * 0.4).set_opacity(0.4),
            server_top_waves.animate.shift(UP * 0.35).set_opacity(0.45),
            server_ribbons.animate.shift(UP * 0.3).set_opacity(0.35),
            server_glow[2].animate.scale(1.3),
            run_time=1.6,
        )
        self.play(
            server_top_waves.animate.shift(UP * 0.2).set_opacity(0.2),
            server_ribbons.animate.set_opacity(0.2),
            rate_func=there_and_back,
            run_time=1.3,
        )

        caption = Text("Geräte wandeln elektrische Leistung in Wärmelasten um", font_size=24, color=P_WHITE)
        caption.to_edge(DOWN, buff=0.4)
        self.play(FadeIn(caption), run_time=1.0)
        # Hold with VO: plug-load heat explanation
        self.wait(2.2)
        self.wait(1.8)


# --- scene_5 (code_final.py) ---
class ArtificialLightingScene(Scene):
    def construct(self):
        self.camera.background_color = P_DEEP_DARK

        def rising_waves(origin, n=3, color=P_ORANGE, height=0.85, x_spread=0.22):
            ox, oy = float(origin[0]), float(origin[1])
            waves = VGroup()
            for i in range(n):
                x0 = ox + (i - (n - 1) / 2) * x_spread
                phase = i * 0.9

                def _path(t, x0=x0, oy=oy, phase=phase, height=height):
                    return np.array([
                        x0 + np.sin(t * 5.0 + phase) * 0.07,
                        oy + t * height,
                        0.0,
                    ])

                waves.add(
                    ParametricFunction(
                        _path, t_range=[0, 1.0], color=color, stroke_width=2.0
                    ).set_opacity(0.85)
                )
            return waves

        # ── Title ──
        title = scene_title("Wärmebeitrag durch künstliche Beleuchtung")

        # ── Room section (Cooling line-art) ──
        room_w, room_h = 8.4, 4.2
        bl = LEFT * (room_w / 2) + DOWN * 2.15
        br = RIGHT * (room_w / 2) + DOWN * 2.15
        tl = LEFT * (room_w / 2) + UP * 2.05
        tr = RIGHT * (room_w / 2) + UP * 2.05

        floor = Line(bl, br, color=P_TEAL, stroke_width=5)
        left_wall = Line(bl, tl, color=P_WHITE, stroke_width=3)
        right_wall = Line(br, tr, color=P_WHITE, stroke_width=3)
        ceiling = Line(tl, tr, color=P_WHITE, stroke_width=3)

        # Drop ceiling / plenum separator
        drop_y = 0.95
        drop_ceiling = DashedLine(
            LEFT * (room_w / 2 - 0.08) + UP * drop_y,
            RIGHT * (room_w / 2 - 0.08) + UP * drop_y,
            color=P_CYAN,
            stroke_width=2,
            dash_length=0.18,
        )

        room = VGroup(floor, left_wall, right_wall, ceiling, drop_ceiling)

        # Zone chips — kept clear of heat labels / fixtures
        plenum_chip = Text("Deckenhohlraum", font_size=16, color=P_CYAN)
        plenum_chip.next_to(ceiling, DOWN, buff=0.12)
        plenum_chip.align_to(left_wall, LEFT).shift(RIGHT * 0.25)
        room_chip = Text("Konditionierter Raum", font_size=16, color=P_TEAL)
        room_chip.next_to(floor, UP, buff=0.18)
        room_chip.align_to(left_wall, LEFT).shift(RIGHT * 0.25)

        # ── Recessed fixtures ──
        def make_fixture(x):
            body = RoundedRectangle(
                width=1.35,
                height=0.22,
                corner_radius=0.06,
                color=P_CYAN,
                stroke_width=2,
                fill_color="#12151C",
                fill_opacity=1.0,
            ).move_to(RIGHT * x + UP * drop_y)
            lens = Line(
                body.get_left() + RIGHT * 0.18,
                body.get_right() + LEFT * 0.18,
                color=P_YELLOW,
                stroke_width=3,
                stroke_opacity=0.35,
            )
            return VGroup(body, lens), body.get_center()

        fixture_l, fix_l_c = make_fixture(-2.0)
        fixture_r, fix_r_c = make_fixture(2.0)
        fixtures = VGroup(fixture_l, fixture_r)

        fixture_label = Text("Deckenleuchten", font_size=20, color=P_YELLOW)
        fixture_label.next_to(fixtures, DOWN, buff=0.35)

        # ── Soft light cones + floor pools ──
        def light_cone(cx, half_w=1.55):
            top = np.array([cx, drop_y - 0.12, 0.0])
            return Polygon(
                top,
                np.array([cx - half_w, -2.05, 0.0]),
                np.array([cx + half_w, -2.05, 0.0]),
                color=P_YELLOW,
                stroke_width=0,
                fill_color=P_YELLOW,
                fill_opacity=0.18,
            )

        cone_l = light_cone(-2.0)
        cone_r = light_cone(2.0)
        pool_l = Ellipse(
            width=3.0, height=0.28, color=P_YELLOW,
            fill_color=P_YELLOW, fill_opacity=0.35, stroke_width=0,
        ).move_to(LEFT * 2.0 + DOWN * 2.05)
        pool_r = Ellipse(
            width=3.0, height=0.28, color=P_YELLOW,
            fill_color=P_YELLOW, fill_opacity=0.35, stroke_width=0,
        ).move_to(RIGHT * 2.0 + DOWN * 2.05)

        # ── Heat: up into plenum, down into room (wavy radiation) ──
        heat_up_l = rising_waves(fix_l_c + UP * 0.12, n=3, color=P_RED, height=0.75, x_spread=0.2)
        heat_up_r = rising_waves(fix_r_c + UP * 0.12, n=3, color=P_RED, height=0.75, x_spread=0.2)
        heat_dn_l = rising_waves(fix_l_c + DOWN * 0.2, n=3, color=P_ORANGE, height=-1.15, x_spread=0.24)
        heat_dn_r = rising_waves(fix_r_c + DOWN * 0.2, n=3, color=P_ORANGE, height=-1.15, x_spread=0.24)
        # Fix downward: ParametricFunction with negative height still works if t*height goes down

        # Heat callouts outside the room (right margin) — left edge clear of white wall
        plenum_heat = Text("Wärme in den Hohlraum", font_size=17, color=P_RED)
        plenum_heat.next_to(right_wall, RIGHT, buff=0.3)
        plenum_heat.set_y(1.5)

        room_heat = Text("Wärme in den Raum", font_size=17, color=P_ORANGE)
        room_heat.next_to(right_wall, RIGHT, buff=0.3)
        room_heat.set_y(-0.45)

        # Soft room warm wash (subtle)
        warm_wash = Rectangle(
            width=room_w - 0.25,
            height=drop_y + 2.05 - 0.15,
            stroke_width=0,
            fill_color=P_ORANGE,
            fill_opacity=0.0,
        ).move_to(DOWN * ((2.05 - drop_y) / 2))

        # One expanded formula card (no duplicate f_g)
        eq_main = Text("Q̇_Licht = Σ P_Licht · f_g", font_size=22, color=P_WHITE)
        eq_p = Text("P_Licht  =  installierte Leistung der Leuchten", font_size=16, color=P_CYAN)
        eq_f = Text("f_g       =  Gleichzeitigkeitsfaktor", font_size=16, color=P_YELLOW)
        eq_f_sub = Text("(Anteil der gleichzeitig betriebenen Leuchten)", font_size=14, color=P_TEAL)
        eq_body = VGroup(eq_main, eq_p, eq_f, eq_f_sub).arrange(DOWN, aligned_edge=LEFT, buff=0.12)
        eq_box = SurroundingRectangle(
            eq_body, color=P_TEAL, corner_radius=0.12, buff=0.2, stroke_width=2.5
        )
        eq_group = VGroup(eq_box, eq_body)

        caption = Text(
            "Beleuchtung wandelt elektrische Leistung in Licht und Wärme um",
            font_size=17,
            color=P_WHITE,
        )
        caption.to_edge(DOWN, buff=0.22)
        eq_group.next_to(caption, UP, buff=0.22)
        eq_group.set_x(0)

        # ── Animation ──
        play_typed_title(self, title)
        self.play(Create(room), run_time=1.6)
        self.play(
            FadeIn(plenum_chip, shift=DOWN * 0.1),
            FadeIn(room_chip, shift=UP * 0.1),
            run_time=0.9,
        )

        self.play(FadeIn(fixtures, shift=DOWN * 0.15), run_time=1.0)
        self.play(FadeIn(fixture_label), run_time=0.6)

        # Lights on
        self.play(
            fixture_l[0].animate.set_fill(P_YELLOW, opacity=0.55),
            fixture_r[0].animate.set_fill(P_YELLOW, opacity=0.55),
            fixture_l[1].animate.set_stroke(opacity=1.0),
            fixture_r[1].animate.set_stroke(opacity=1.0),
            run_time=1.0,
        )
        self.play(
            FadeIn(cone_l),
            FadeIn(cone_r),
            FadeIn(pool_l),
            FadeIn(pool_r),
            FadeOut(fixture_label),
            run_time=1.4,
        )
        self.play(
            cone_l.animate.set_fill(opacity=0.28),
            cone_r.animate.set_fill(opacity=0.28),
            rate_func=there_and_back,
            run_time=1.1,
        )

        # Heat splits: upward into plenum + downward into room
        self.play(
            FadeOut(plenum_chip),
            LaggedStart(
                *[Create(w) for w in heat_up_l],
                *[Create(w) for w in heat_up_r],
                lag_ratio=0.06,
            ),
            FadeIn(plenum_heat),
            run_time=1.5,
        )
        self.play(
            heat_up_l.animate.shift(UP * 0.2).set_opacity(0.45),
            heat_up_r.animate.shift(UP * 0.2).set_opacity(0.45),
            run_time=1.0,
        )
        self.play(
            FadeOut(room_chip),
            LaggedStart(
                *[Create(w) for w in heat_dn_l],
                *[Create(w) for w in heat_dn_r],
                lag_ratio=0.06,
            ),
            FadeIn(room_heat),
            run_time=1.5,
        )
        self.play(
            heat_dn_l.animate.set_opacity(0.4),
            heat_dn_r.animate.set_opacity(0.4),
            warm_wash.animate.set_fill(opacity=0.10),
            run_time=1.2,
        )

        # Shrink room slightly so formula card has clear space at the bottom
        diagram = VGroup(
            room, fixtures, cone_l, cone_r, pool_l, pool_r,
            heat_up_l, heat_up_r, heat_dn_l, heat_dn_r, warm_wash,
            plenum_heat, room_heat, title,
        )
        self.play(
            diagram.animate.scale(0.88).shift(UP * 0.35),
            run_time=0.9,
        )

        # Equation via morph: luminaires → P_Licht, then assemble formula (no orphan equation)
        p_token = symbol_token("P_Licht", color=P_CYAN, font_size=26)
        p_token.move_to(fixtures.get_center())
        fg_token = symbol_token("f_g", color=P_YELLOW, font_size=26)
        fg_token.move_to(eq_main.get_center() + RIGHT * 1.6)

        self.play(
            ReplacementTransform(fixtures.copy(), p_token),
            run_time=1.3,
        )
        self.play(
            p_token.animate.move_to(eq_p.get_left() + RIGHT * 0.9),
            FadeIn(eq_box),
            FadeIn(eq_main),
            run_time=1.2,
        )
        self.play(FadeIn(eq_p), FadeOut(p_token), run_time=0.8)
        self.play(FadeIn(eq_f), FadeIn(eq_f_sub), FadeIn(caption), run_time=1.0)
        fg_hl = SurroundingRectangle(
            VGroup(eq_f, eq_f_sub),
            color=P_YELLOW,
            buff=0.08,
            stroke_width=2,
            corner_radius=0.06,
        )
        self.play(Create(fg_hl), run_time=0.7)
        self.play(FadeOut(fg_hl), run_time=0.4)

        self.wait(0.5)


# --- scene_6 (code_final.py) ---
class InternalGainEquation(Scene):
    def construct(self):
        self.camera.background_color = P_DEEP_DARK

        def mini_person(center=ORIGIN):
            """ISO-style academic occupant pictogram (architecture / building physics)."""
            head = Circle(
                radius=0.13,
                color=P_ORANGE,
                stroke_width=2.3,
                fill_color=P_ORANGE,
                fill_opacity=0.18,
            ).move_to(center + UP * 0.26)
            shoulders = Arc(
                radius=0.24,
                start_angle=0,
                angle=PI,
                color=P_ORANGE,
                stroke_width=2.5,
            )
            shoulders.next_to(head, DOWN, buff=0.03)
            return VGroup(head, shoulders)

        def mini_laptop(center=ORIGIN):
            base = Rectangle(width=0.62, height=0.07, color=P_CYAN, stroke_width=2).move_to(center + DOWN * 0.04)
            screen = Rectangle(width=0.48, height=0.3, color=P_CYAN, stroke_width=2).move_to(center + UP * 0.18)
            return VGroup(base, screen)

        def mini_lamp(center=ORIGIN):
            cord = Line(center + UP * 0.38, center + UP * 0.12, color=P_WHITE, stroke_width=1.5)
            bulb = Circle(radius=0.14, color=P_YELLOW, stroke_width=2, fill_opacity=0.35).move_to(center)
            return VGroup(cord, bulb)

        def source_card(icon, title_de, term, color, center):
            """Compact icon card — formulas live outside, below the box."""
            frame = RoundedRectangle(
                width=2.15, height=1.85, corner_radius=0.12,
                color=color, stroke_width=2.2, fill_color="#12151C", fill_opacity=0.92,
            ).move_to(center)
            title = Text(title_de, font_size=16, color=color)
            title.next_to(frame.get_top(), DOWN, buff=0.12)
            icon.move_to(center + DOWN * 0.05)
            term_t = Text(term, font_size=18, color=P_WHITE)
            term_t.next_to(frame.get_bottom(), UP, buff=0.14)
            return VGroup(frame, title, icon, term_t), frame, term_t

        # ── Title ──
        title = scene_title("Die Gleichung für interne Gewinne")
        subtitle = Text("Summe der drei Wärmequellen aus den vorherigen Szenen", font_size=15, color=P_TEAL)
        subtitle.next_to(title, DOWN, buff=0.14)

        # ── Wider spacing so "+" sits cleanly between boxes ──
        c_p = LEFT * 4.35 + UP * 1.05
        c_e = ORIGIN + UP * 1.05
        c_l = RIGHT * 4.35 + UP * 1.05

        card_p, frame_p, term_p = source_card(mini_person(), "Personen", "Q̇_Pers", P_ORANGE, c_p)
        card_e, frame_e, term_e = source_card(mini_laptop(), "Geräte", "Q̇_Geräte", P_CYAN, c_e)
        card_l, frame_l, term_l = source_card(mini_lamp(), "Beleuchtung", "Q̇_Licht", P_YELLOW, c_l)

        plus_1 = Text("+", font_size=40, color=P_WHITE)
        plus_1.move_to((c_p + c_e) / 2)
        plus_2 = Text("+", font_size=40, color=P_WHITE)
        plus_2.move_to((c_e + c_l) / 2)

        # Formulas OUTSIDE boxes, under each card (readable size)
        expand_p = VGroup(
            Text("Q̇_Pers = n · q̇_p", font_size=20, color=P_WHITE),
            Text("n · ~100 W pro Person", font_size=15, color=P_ORANGE),
        ).arrange(DOWN, buff=0.1)
        expand_p.next_to(frame_p, DOWN, buff=0.35)

        expand_e = VGroup(
            Text("Q̇_Geräte = Σ P_el · f_N", font_size=19, color=P_WHITE),
            Text("P_el · Nutzungsfaktor f_N", font_size=15, color=P_CYAN),
        ).arrange(DOWN, buff=0.1)
        expand_e.next_to(frame_e, DOWN, buff=0.35)

        expand_l = VGroup(
            Text("Q̇_Licht = Σ P_Licht · f_g", font_size=19, color=P_WHITE),
            Text("P_Licht · Gleichzeitigkeit f_g", font_size=15, color=P_YELLOW),
        ).arrange(DOWN, buff=0.1)
        expand_l.next_to(frame_l, DOWN, buff=0.35)

        # Heat accents (echo prior scenes), clipped near icons
        rings_p = VGroup(*[
            Circle(radius=0.28 + i * 0.18, color=P_ORANGE, stroke_width=1.5, stroke_opacity=0.65 - i * 0.15)
            for i in range(3)
        ]).move_to(c_p + DOWN * 0.05)

        def short_waves(origin, color=P_ORANGE):
            ox, oy = float(origin[0]), float(origin[1])
            waves = VGroup()
            for i, dx in enumerate([-0.14, 0.0, 0.14]):
                phase = i * 0.8

                def _path(t, x0=ox + dx, oy=oy, phase=phase):
                    return np.array([x0 + np.sin(t * 5 + phase) * 0.04, oy + t * 0.4, 0.0])

                waves.add(
                    ParametricFunction(_path, t_range=[0, 1], color=color, stroke_width=1.5).set_opacity(0.7)
                )
            return waves

        waves_e = short_waves(c_e + UP * 0.2, P_CYAN)
        waves_l = short_waves(c_l + UP * 0.15, P_YELLOW)

        # Master equation (no arrows)
        m_qi = Text("Q̇_i", font_size=28, color=P_CYAN)
        m_eq = Text(" = ", font_size=28, color=P_WHITE)
        m_p = Text("Q̇_Pers", font_size=24, color=P_ORANGE)
        m_p1 = Text(" + ", font_size=24, color=P_WHITE)
        m_e = Text("Q̇_Geräte", font_size=24, color=P_CYAN)
        m_p2 = Text(" + ", font_size=24, color=P_WHITE)
        m_l = Text("Q̇_Licht", font_size=24, color=P_YELLOW)
        master = VGroup(m_qi, m_eq, m_p, m_p1, m_e, m_p2, m_l).arrange(RIGHT, buff=0.12)
        master_box = SurroundingRectangle(
            master, color=P_ORANGE, corner_radius=0.12, buff=0.2, stroke_width=2.8
        )
        master_group = VGroup(master_box, master)
        master_group.to_edge(DOWN, buff=1.15)

        meaning = Text("Q̇_i  =  gesamte interne Kühllast  [W]", font_size=17, color=P_WHITE)
        meaning.next_to(master_group, DOWN, buff=0.22)

        caption = Text("Drei Quellen → eine Bilanzgleichung", font_size=16, color=P_TEAL)
        caption.to_edge(DOWN, buff=0.22)

        # ── Animation ──
        play_typed_title(self, title)
        self.play(FadeIn(subtitle), run_time=0.55)

        self.play(
            LaggedStart(FadeIn(card_p), FadeIn(card_e), FadeIn(card_l), lag_ratio=0.22),
            run_time=1.4,
        )
        self.play(FadeIn(plus_1), FadeIn(plus_2), run_time=0.55)

        self.play(
            LaggedStart(*[Create(r) for r in rings_p], lag_ratio=0.2),
            LaggedStart(*[Create(w) for w in waves_e], lag_ratio=0.1),
            LaggedStart(*[Create(w) for w in waves_l], lag_ratio=0.1),
            run_time=1.4,
        )
        self.play(
            rings_p.animate.scale(1.12).set_stroke(opacity=0.3),
            waves_e.animate.shift(UP * 0.12).set_opacity(0.3),
            waves_l.animate.shift(UP * 0.12).set_opacity(0.3),
            rate_func=there_and_back,
            run_time=1.0,
        )

        # Reveal formulas BELOW boxes, one by one
        self.play(
            frame_p.animate.set_stroke(width=3.2),
            FadeIn(expand_p, shift=UP * 0.15),
            run_time=0.95,
        )
        self.play(frame_p.animate.set_stroke(width=2.2), run_time=0.25)
        self.wait(0.25)

        self.play(
            frame_e.animate.set_stroke(width=3.2),
            FadeIn(expand_e, shift=UP * 0.15),
            run_time=0.95,
        )
        self.play(frame_e.animate.set_stroke(width=2.2), run_time=0.25)
        self.wait(0.25)

        self.play(
            frame_l.animate.set_stroke(width=3.2),
            FadeIn(expand_l, shift=UP * 0.15),
            run_time=0.95,
        )
        self.play(frame_l.animate.set_stroke(width=2.2), run_time=0.25)
        self.wait(0.3)

        # Clear accents + per-source formulas, keep cards, show master sum
        self.play(
            FadeOut(rings_p), FadeOut(waves_e), FadeOut(waves_l),
            FadeOut(expand_p), FadeOut(expand_e), FadeOut(expand_l),
            run_time=0.8,
        )

        # Lift cards slightly and reveal master equation (no arrows)
        self.play(
            VGroup(card_p, card_e, card_l, plus_1, plus_2).animate.shift(UP * 0.25),
            run_time=0.7,
        )
        self.play(Create(master_box), FadeIn(master, shift=UP * 0.12), run_time=1.2)

        for term, color in ((m_p, P_ORANGE), (m_e, P_CYAN), (m_l, P_YELLOW)):
            hl = SurroundingRectangle(term, color=color, buff=0.06, stroke_width=2.4, corner_radius=0.05)
            self.play(Create(hl), run_time=0.32)
            self.play(FadeOut(hl), run_time=0.22)

        qi_hl = SurroundingRectangle(m_qi, color=P_CYAN, buff=0.08, stroke_width=2.8, corner_radius=0.05)
        self.play(Create(qi_hl), FadeIn(meaning), run_time=0.75)
        self.play(qi_hl.animate.set_color(P_WHITE), rate_func=there_and_back, run_time=0.7)
        self.play(FadeOut(qi_hl), FadeIn(caption), run_time=0.55)

        # Hold with VO: internal-gain balance equation
        self.wait(1.8)


