class SensibleVsLatentHeat(Scene):
    def construct(self):
        self.camera.background_color = P_DEEP_DARK

        # --- Beat 1: Title & Screen Division (4.0s) ---
        title = scene_title("Sensible versus latente Wärme")

        divider = Line(UP * 2.2, DOWN * 2.4, color="#475569", stroke_width=2)

        left_header = Text("Sensible Last", font_size=30, color="#FF5B5B")
        left_header.move_to(np.array([-3.4, 2.5, 0]))

        left_sub = Text("Temperaturanstieg", font_size=24, color="#CBD5E1")
        left_sub.next_to(left_header, DOWN, buff=0.12)

        right_header = Text("Latente Feuchtigkeit", font_size=30, color="#38BDF8")
        right_header.move_to(np.array([3.4, 2.5, 0]))

        right_sub = Text("Phasen- / Feuchtigkeitswechsel", font_size=24, color="#CBD5E1")
        right_sub.next_to(right_header, DOWN, buff=0.12)

        play_typed_title(self, title)
        self.play(Create(divider), run_time=1.0)
        self.play(
            FadeIn(left_header), FadeIn(left_sub),
            FadeIn(right_header), FadeIn(right_sub),
            run_time=2.0
        )

        # --- Beat 2: Left Panel - Sensible Heat Thermometer Setup (4.0s) ---
        bulb = Circle(radius=0.45, color="#FF5B5B", fill_color="#0F172A", fill_opacity=1.0, stroke_width=3)
        bulb.move_to(np.array([-3.4, -1.8, 0]))

        tube = RoundedRectangle(corner_radius=0.15, height=2.6, width=0.4, color="#FF5B5B", stroke_width=3)
        tube.move_to(np.array([-3.4, -0.2, 0]))

        mercury_bulb = Circle(radius=0.42, color="#FF5B5B", fill_color="#FF5B5B", fill_opacity=0.9, stroke_width=0)
        mercury_bulb.move_to(np.array([-3.4, -1.8, 0]))

        temp_ticks = VGroup(*[
            Line([-3.65, y, 0], [-3.5, y, 0], color="#94A3B8", stroke_width=2)
            for y in np.linspace(-1.2, 0.9, 6)
        ])

        sensible_tag = Text("Misst Lufttemperatur", font_size=20, color="#FF8A8A")
        sensible_tag.move_to(np.array([-3.4, -2.5, 0]))

        temp_tracker = ValueTracker(0.2)

        column = always_redraw(lambda: Rectangle(
            width=0.26,
            height=max(0.05, temp_tracker.get_value()),
            color="#FF5B5B",
            fill_color="#FF5B5B",
            fill_opacity=0.9,
            stroke_width=0
        ).move_to(np.array([-3.4, -1.45 + temp_tracker.get_value() / 2, 0])))

        temp_label = always_redraw(lambda: Text(
            f"{int(21 + temp_tracker.get_value() * 5)}°C",
            font_size=22,
            color="#FF8A8A"
        ).move_to(np.array([-2.2, -1.4 + temp_tracker.get_value(), 0])))

        self.play(
            Create(bulb), Create(tube), Create(temp_ticks), FadeIn(mercury_bulb),
            run_time=2.0
        )
        self.play(
            FadeIn(sensible_tag), FadeIn(column), FadeIn(temp_label),
            run_time=2.0
        )

        # --- Beat 3: Right Panel - Latent Moisture Container Setup (4.0s) ---
        container = RoundedRectangle(corner_radius=0.1, height=2.5, width=1.3, color="#38BDF8", stroke_width=3)
        container.move_to(np.array([3.4, -0.3, 0]))

        moist_ticks = VGroup(*[
            Line([2.65, y, 0], [2.75, y, 0], color="#94A3B8", stroke_width=2)
            for y in np.linspace(-1.3, 0.7, 5)
        ])

        latent_tag = Text("Misst Wasserdampf", font_size=20, color="#7DD3FC")
        latent_tag.move_to(np.array([3.4, -2.5, 0]))

        droplet_group = VGroup(*[
            Circle(radius=0.08, color="#38BDF8", fill_color="#38BDF8", fill_opacity=0.85, stroke_width=1)
            .move_to(np.array([3.4 + dx, 1.2 + dy, 0]))
            for dx, dy in [(-0.35, 0.1), (-0.1, 0.45), (0.2, 0.2), (0.4, -0.1)]
        ])

        moist_tracker = ValueTracker(0.25)

        water_fill = always_redraw(lambda: Rectangle(
            width=1.18,
            height=max(0.05, moist_tracker.get_value() * 2.0),
            color="#0284C7",
            fill_color="#38BDF8",
            fill_opacity=0.75,
            stroke_width=0
        ).move_to(np.array([3.4, -1.55 + (moist_tracker.get_value() * 2.0) / 2, 0])))

        rh_label = always_redraw(lambda: Text(
            f"{int(30 + moist_tracker.get_value() * 60)}% r.F.",
            font_size=22,
            color="#7DD3FC"
        ).move_to(np.array([4.7, -1.55 + moist_tracker.get_value() * 2.0, 0])))

        self.play(Create(container), Create(moist_ticks), run_time=2.0)
        self.play(
            FadeIn(latent_tag), FadeIn(water_fill), FadeIn(rh_label), FadeIn(droplet_group),
            run_time=2.0
        )

        # --- Beat 4: Gauges Fill Simultaneously & Summary Banner (6.5s) ---
        summary = Text("Gesamtwärmelast = Sensible Last + Latente Last", font_size=24, color=P_WHITE)
        summary.to_edge(DOWN, buff=0.4)

        self.play(
            temp_tracker.animate.set_value(2.2),
            moist_tracker.animate.set_value(0.95),
            droplet_group.animate.shift(DOWN * 1.1).set_opacity(0.2),
            run_time=4.5
        )
        self.play(FadeIn(summary), run_time=2.0)

        # --- Final Hold (0.5s) ---
        self.wait(0.5)


# --- scene_8 (code_final.py) ---
class Scene8(Scene):
    def construct(self):
        """Insulated heat trap: particles hit the wall, heat up, and fill the room."""
        self.camera.background_color = P_DEEP_DARK

        C_LIGHT = "#FFC9A8"
        C_SHARP = "#FF9A6B"
        C_HOT = "#FF6B35"
        C_VERY_HOT = "#FF4500"

        title = scene_title("Die isolierte Wärmefalle")
        subtitle = Text("Interne Gewinne bleiben im gut gedämmten Raum", font_size=16, color=P_TEAL)
        subtitle.next_to(title, DOWN, buff=0.15)

        room_c = DOWN * 0.2
        inner_w, inner_h = 4.6, 2.6
        ins_t = 0.55
        r_dot = 0.09

        inner = Rectangle(
            width=inner_w, height=inner_h,
            color=P_WHITE, stroke_width=3.5, fill_opacity=0,
        ).move_to(room_c)
        outer = Rectangle(
            width=inner_w + 2 * ins_t, height=inner_h + 2 * ins_t,
            color=P_CYAN, stroke_width=2.5, fill_opacity=0,
        ).move_to(room_c)

        top_ins = Rectangle(
            width=inner_w + 2 * ins_t, height=ins_t,
            stroke_width=0, fill_color=P_ORANGE, fill_opacity=0.25,
        ).move_to(room_c + UP * ((inner_h + ins_t) / 2))
        bot_ins = Rectangle(
            width=inner_w + 2 * ins_t, height=ins_t,
            stroke_width=0, fill_color=P_ORANGE, fill_opacity=0.25,
        ).move_to(room_c + DOWN * ((inner_h + ins_t) / 2))
        left_ins = Rectangle(
            width=ins_t, height=inner_h,
            stroke_width=0, fill_color=P_ORANGE, fill_opacity=0.25,
        ).move_to(room_c + LEFT * ((inner_w + ins_t) / 2))
        right_ins = Rectangle(
            width=ins_t, height=inner_h,
            stroke_width=0, fill_color=P_ORANGE, fill_opacity=0.25,
        ).move_to(room_c + RIGHT * ((inner_w + ins_t) / 2))
        insulation = VGroup(top_ins, bot_ins, left_ins, right_ins)

        floor_line = Line(
            room_c + LEFT * (inner_w / 2) + DOWN * (inner_h / 2),
            room_c + RIGHT * (inner_w / 2) + DOWN * (inner_h / 2),
            color=P_TEAL, stroke_width=4,
        )
        warm_fill = Rectangle(
            width=inner_w - 0.06, height=inner_h - 0.06,
            stroke_width=0, fill_color=C_LIGHT, fill_opacity=0.0,
        ).move_to(room_c)

        room_lbl = Text("Innenraum", font_size=16, color=P_TEAL)
        room_lbl.next_to(floor_line, UP, buff=0.12)

        ins_lbl = VGroup(
            Text("Dämmung", font_size=18, color=P_ORANGE),
            Text("Isolationsschicht", font_size=14, color=P_TEAL),
        ).arrange(DOWN, buff=0.08, aligned_edge=LEFT)
        ins_lbl.next_to(outer, RIGHT, buff=0.35)
        ins_lbl.set_y(room_c[1] + 1.05)

        # Movement copy: centered under the floor, outside the outer boundary
        explain_out = Text("Wärmeteilchen wandern zur Wand", font_size=15, color=C_LIGHT)
        explain_back = Text(
            "Dämmung wirft sie zurück — sie werden heißer",
            font_size=15,
            color=C_SHARP,
        )
        explain_anchor_y = float(outer.get_bottom()[1]) - 0.38
        explain_out.move_to([room_c[0], explain_anchor_y, 0])
        explain_back.move_to([room_c[0], explain_anchor_y, 0])

        trapped_lbl = Text("Eingeschlossene Wärme", font_size=20, color=C_VERY_HOT)
        trapped_lbl.move_to(room_c)

        caption = Text(
            "Gute Dämmung hält interne Gewinne im Raum — Kühlbedarf steigt",
            font_size=17,
            color=P_WHITE,
        )
        caption.to_edge(DOWN, buff=0.22)

        rng = np.random.default_rng(7)
        n_particles = 18
        # Dot centers stop so the disk edge touches the inner wall stroke
        wall_x = inner_w / 2 - r_dot
        wall_y = inner_h / 2 - r_dot
        spawn_w, spawn_h = wall_x * 0.5, wall_y * 0.5

        starts = [
            room_c + np.array([
                float(rng.uniform(-spawn_w, spawn_w)),
                float(rng.uniform(-spawn_h, spawn_h)),
                0.0,
            ])
            for _ in range(n_particles)
        ]

        def make_wall_hits(seed_shift=0):
            hits = []
            for i in range(n_particles):
                side = (i + seed_shift) % 4
                if side == 0:
                    hits.append(np.array([room_c[0] + wall_x, float(rng.uniform(-wall_y, wall_y)), 0.0]))
                elif side == 1:
                    hits.append(np.array([room_c[0] - wall_x, float(rng.uniform(-wall_y, wall_y)), 0.0]))
                elif side == 2:
                    hits.append(np.array([float(rng.uniform(-wall_x, wall_x)), room_c[1] + wall_y, 0.0]))
                else:
                    hits.append(np.array([float(rng.uniform(-wall_x, wall_x)), room_c[1] - wall_y, 0.0]))
            return hits

        def make_interior(scale=0.45):
            return [
                room_c + np.array([
                    float(rng.uniform(-wall_x * scale, wall_x * scale)),
                    float(rng.uniform(-wall_y * scale, wall_y * scale)),
                    0.0,
                ])
                for _ in range(n_particles)
            ]

        wall_1 = make_wall_hits(0)
        back_1 = make_interior(0.45)
        wall_2 = make_wall_hits(1)
        back_2 = make_interior(0.4)
        wall_3 = make_wall_hits(2)
        back_3 = make_interior(0.35)

        particles = VGroup(*[
            Dot(point=s, radius=r_dot, color=C_LIGHT, fill_opacity=1.0, stroke_width=0)
            for s in starts
        ])

        # Continuous bounce paths: start → wall → interior → wall → … (no pauses)
        paths = VGroup()
        for i in range(n_particles):
            path = VMobject()
            path.set_points_as_corners([
                starts[i], wall_1[i], back_1[i],
                wall_2[i], back_2[i],
                wall_3[i], back_3[i],
            ])
            paths.add(path)

        # Path alphas at wall contacts (6 equal corner segments)
        a_wall_1, a_wall_2, a_wall_3 = 1 / 6, 3 / 6, 5 / 6

        def heat_progress(mob, alpha):
            if alpha < a_wall_1:
                color, fill_c, fill_op = C_LIGHT, C_LIGHT, 0.0
            elif alpha < a_wall_2:
                t = (alpha - a_wall_1) / (a_wall_2 - a_wall_1)
                color, fill_c, fill_op = C_SHARP, C_LIGHT, 0.12 + 0.16 * t
            elif alpha < a_wall_3:
                t = (alpha - a_wall_2) / (a_wall_3 - a_wall_2)
                color, fill_c, fill_op = C_HOT, C_SHARP, 0.28 + 0.17 * t
            else:
                t = (alpha - a_wall_3) / max(1e-6, 1.0 - a_wall_3)
                color, fill_c, fill_op = C_VERY_HOT, C_HOT, 0.45 + 0.2 * t
            for p in particles:
                p.set_color(color)
            warm_fill.set_fill(fill_c, opacity=float(fill_op))

        # ── Animation ──
        self.add(warm_fill)
        play_typed_title(self, title)
        self.play(FadeIn(subtitle), run_time=0.55)
        self.play(Create(inner), Create(floor_line), FadeIn(room_lbl), run_time=1.2)
        self.play(Create(outer), FadeIn(insulation), FadeIn(ins_lbl), run_time=1.2)

        self.play(
            LaggedStart(*[FadeIn(p, scale=0.5) for p in particles], lag_ratio=0.03),
            FadeIn(explain_out),
            run_time=1.0,
        )

        motion_rt = 8.5
        self.play(
            AnimationGroup(*[
                MoveAlongPath(p, path, rate_func=linear)
                for p, path in zip(particles, paths)
            ]),
            UpdateFromAlphaFunc(particles, heat_progress),
            Succession(
                Wait(motion_rt * a_wall_1),
                AnimationGroup(FadeOut(explain_out), FadeIn(explain_back), run_time=0.45),
                Wait(motion_rt * (1.0 - a_wall_1) - 0.45),
            ),
            run_time=motion_rt,
        )

        self.play(
            FadeOut(explain_back),
            FadeOut(room_lbl),
            FadeOut(particles),
            warm_fill.animate.set_fill(C_VERY_HOT, opacity=0.72),
            insulation.animate.set_fill(opacity=0.38),
            FadeIn(trapped_lbl),
            run_time=1.4,
        )
        self.play(FadeIn(caption), run_time=0.8)
        self.wait(0.5)


# --- scene_9 (code_final.py) ---
class Scene9(Scene):
    def construct(self):
        """HLK removes trapped internal heat: return extracts, supply displaces."""
        self.camera.background_color = P_DEEP_DARK

        C_HEAT = "#FFC9A8"
        C_HEAT_MID = "#FF7B54"
        C_HEAT_HOT = "#FF4500"
        C_COOL = P_CYAN
        C_COOL_DIM = P_TEAL
        C_WALL = P_WHITE

        title = scene_title("HLK-Kühlbedarf")
        subtitle = Text(
            "Kühlluft verdrängt die interne Wärmelast",
            font_size=16,
            color=C_COOL_DIM,
        )
        subtitle.next_to(title, DOWN, buff=0.12)

        room_c = DOWN * 0.15
        room_w, room_h = 7.0, 3.4
        r_dot = 0.085
        room = Rectangle(
            width=room_w, height=room_h,
            color=C_WALL, stroke_width=3.5, fill_opacity=0,
        ).move_to(room_c)
        floor = Line(
            room.get_corner(DL), room.get_corner(DR),
            color=C_COOL_DIM, stroke_width=4,
        )

        warm_fill = Rectangle(
            width=room_w - 0.08, height=room_h - 0.08,
            stroke_width=0, fill_color=C_HEAT_HOT, fill_opacity=0.0,
        ).move_to(room_c)
        cool_fill = Rectangle(
            width=room_w - 0.08, height=room_h - 0.08,
            stroke_width=0, fill_color=C_COOL, fill_opacity=0.0,
        ).move_to(room_c)

        vent_w, vent_h = 1.35, 0.28
        supply = RoundedRectangle(
            width=vent_w, height=vent_h, corner_radius=0.06,
            color=C_COOL, stroke_width=2.5,
            fill_color=C_COOL, fill_opacity=0.2,
        ).move_to(room.get_top() + DOWN * 0.22 + LEFT * 2.15)
        ret = RoundedRectangle(
            width=vent_w, height=vent_h, corner_radius=0.06,
            color=C_HEAT_HOT, stroke_width=2.5,
            fill_color=C_HEAT_HOT, fill_opacity=0.2,
        ).move_to(room.get_top() + DOWN * 0.22 + RIGHT * 2.15)

        def vent_grille(vent, color):
            lines = VGroup()
            for t in (-0.35, 0.0, 0.35):
                lines.add(Line(
                    vent.get_left() + RIGHT * 0.18 + UP * t * 0.08,
                    vent.get_right() + LEFT * 0.18 + UP * t * 0.08,
                    color=color, stroke_width=1.5, stroke_opacity=0.85,
                ))
            return lines

        supply_grille = vent_grille(supply, C_COOL)
        ret_grille = vent_grille(ret, C_HEAT_MID)

        lbl_supply = VGroup(
            Text("Zuluft", font_size=18, color=C_COOL),
            Text("kühl", font_size=13, color=C_COOL_DIM),
        ).arrange(DOWN, buff=0.04)
        lbl_supply.next_to(supply, UP, buff=0.18)

        lbl_return = VGroup(
            Text("Abluft", font_size=18, color=C_HEAT_MID),
            Text("warm", font_size=13, color=C_HEAT),
        ).arrange(DOWN, buff=0.04)
        lbl_return.next_to(ret, UP, buff=0.18)

        step1 = Text("1  Interne Wärme staut sich im Raum", font_size=16, color=C_HEAT)
        step2 = Text("2  Abluft saugt warme Luft ab", font_size=16, color=C_HEAT_MID)
        step3 = Text("3  Zuluft bringt Kühlluft nach", font_size=16, color=C_COOL)
        for s in (step1, step2, step3):
            s.move_to([room_c[0], float(room.get_bottom()[1]) - 0.42, 0])

        caption = Text(
            "Aktive Verdrängung der Wärmelast → HLK-Kühlbedarf",
            font_size=18,
            color=P_WHITE,
        )
        caption.to_edge(DOWN, buff=0.22)

        rng = np.random.default_rng(42)
        wall_x = room_w / 2 - r_dot
        wall_y = room_h / 2 - r_dot
        # Keep particles clear of ceiling vents while bouncing in the room
        bounce_top = wall_y - 0.45

        def wall_point(side):
            if side == 0:  # right
                return room_c + np.array([wall_x, float(rng.uniform(-wall_y, bounce_top)), 0.0])
            if side == 1:  # left
                return room_c + np.array([-wall_x, float(rng.uniform(-wall_y, bounce_top)), 0.0])
            if side == 2:  # top (below vents)
                return room_c + np.array([float(rng.uniform(-wall_x, wall_x)), bounce_top, 0.0])
            return room_c + np.array([float(rng.uniform(-wall_x, wall_x)), -wall_y, 0.0])

        def interior_point(scale=0.55):
            return room_c + np.array([
                float(rng.uniform(-wall_x * scale, wall_x * scale)),
                float(rng.uniform(-wall_y * scale, bounce_top * scale)),
                0.0,
            ])

        def bounce_waypoints(start, n_bounces, seed_shift=0):
            pts = [np.array(start, dtype=float)]
            for k in range(n_bounces):
                pts.append(wall_point((k + seed_shift) % 4))
                pts.append(interior_point(0.4 + 0.08 * (k % 3)))
            return pts

        def path_from_points(pts):
            path = VMobject()
            path.set_points_as_corners(pts)
            return path

        def vent_into_room_points(vent, from_left, n_bounces, seed_shift):
            """Zuluft-style path: leave ceiling vent, then bounce through the room."""
            start = vent.get_bottom() + DOWN * 0.08 + np.array([
                float(rng.uniform(-0.4, 0.4)), 0.0, 0.0,
            ])
            if from_left:
                first = room_c + np.array([
                    float(rng.uniform(-wall_x * 0.5, wall_x * 0.2)),
                    float(rng.uniform(-0.2, bounce_top * 0.4)),
                    0.0,
                ])
            else:
                first = room_c + np.array([
                    float(rng.uniform(-wall_x * 0.2, wall_x * 0.5)),
                    float(rng.uniform(-0.2, bounce_top * 0.4)),
                    0.0,
                ])
            bounce = bounce_waypoints(first, n_bounces=n_bounces, seed_shift=seed_shift)
            return [start, first] + bounce[1:]

        n_flow = 18
        n_bounces = 4
        flow_rt = 12.0

        # Zuluft: vent → room bounces
        cool_paths = VGroup()
        cool_point_lists = []
        for i in range(n_flow):
            pts = vent_into_room_points(supply, from_left=True, n_bounces=n_bounces, seed_shift=i + 1)
            cool_point_lists.append(pts)
            cool_paths.add(path_from_points(pts))

        cool_dots = VGroup(*[
            Dot(
                point=pts[0],
                radius=float(rng.uniform(0.06, 0.1)),
                color=C_COOL,
                fill_opacity=1.0,
                stroke_width=0,
            )
            for pts in cool_point_lists
        ])

        # Abluft: exact reverse of the same vent-flow pattern (room bounces → vent)
        heat_paths = VGroup()
        heat_point_lists = []
        for i in range(n_flow):
            forward = vent_into_room_points(ret, from_left=False, n_bounces=n_bounces, seed_shift=i)
            pts = [np.array(p, dtype=float) for p in reversed(forward)]
            heat_point_lists.append(pts)
            heat_paths.add(path_from_points(pts))

        heat_dots = VGroup(*[
            Dot(
                point=pts[0],
                radius=r_dot,
                color=C_HEAT,
                fill_opacity=1.0,
                stroke_width=0,
            )
            for pts in heat_point_lists
        ])

        heat_lbl = Text("Thermische Last", font_size=22, color=C_HEAT)
        heat_lbl.move_to(room_c + UP * 0.55)

        # ── Beat 1: room + trapped heat ──
        self.add(warm_fill, cool_fill)
        play_typed_title(self, title)
        self.play(FadeIn(subtitle), run_time=0.5)
        self.play(
            Create(room), Create(floor),
            FadeIn(supply), FadeIn(ret),
            FadeIn(supply_grille), FadeIn(ret_grille),
            run_time=1.2,
        )
        self.play(FadeIn(lbl_supply), FadeIn(lbl_return), run_time=0.55)
        self.play(
            FadeIn(step1),
            warm_fill.animate.set_fill(C_HEAT_HOT, opacity=0.22),
            LaggedStart(*[FadeIn(d, scale=0.5) for d in heat_dots], lag_ratio=0.03),
            FadeIn(heat_lbl),
            run_time=1.3,
        )

        # ── Beat 2: Abluft = Zuluft motion reversed (bounce, then into return) ──
        self.play(
            FadeOut(step1),
            FadeIn(step2),
            FadeOut(heat_lbl),
            ret.animate.set_fill(C_HEAT_HOT, opacity=0.55),
            run_time=0.8,
        )

        def warm_progress(mob, alpha):
            warm_fill.set_fill(C_HEAT_HOT, opacity=0.22 - 0.18 * alpha)

        self.play(
            AnimationGroup(*[
                MoveAlongPath(d, path, rate_func=linear)
                for d, path in zip(heat_dots, heat_paths)
            ], lag_ratio=0.04),
            UpdateFromAlphaFunc(warm_fill, warm_progress),
            run_time=flow_rt,
        )
        self.play(FadeOut(heat_dots), run_time=0.45)
        self.wait(0.3)

        # ── Beat 3: Zuluft (same animation pattern, opposite direction) ──
        self.play(
            FadeOut(step2),
            FadeIn(step3),
            supply.animate.set_fill(C_COOL, opacity=0.6),
            run_time=0.8,
        )
        for d, path in zip(cool_dots, cool_paths):
            d.move_to(path.get_start())
        self.add(cool_dots)

        def cool_progress(mob, alpha):
            cool_fill.set_fill(C_COOL, opacity=0.08 + 0.32 * alpha)

        self.play(
            AnimationGroup(*[
                MoveAlongPath(d, path, rate_func=linear)
                for d, path in zip(cool_dots, cool_paths)
            ], lag_ratio=0.04),
            UpdateFromAlphaFunc(cool_fill, cool_progress),
            run_time=flow_rt,
        )

        # ── Beat 4: summary ──
        self.play(
            FadeOut(step3),
            FadeIn(caption),
            cool_dots.animate.set_opacity(0.5),
            run_time=1.0,
        )
        self.wait(0.55)


